css:
.recibo { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #111; }
.recibo table { width: 100%; border-collapse: collapse; }
.recibo td, .recibo th { vertical-align: top; }
.co-name { font-weight: bold; font-size: 12px; }
.dup { margin-top: 16px; font-size: 10px; color: #333; }
.title { font-size: 20px; font-weight: bold; margin: 6px 0 4px; }
.rule { border-top: 2px solid #111; margin: 0 0 12px; }
.info { margin-bottom: 10px; }
.kv .k { font-weight: bold; padding: 1px 10px 1px 0; white-space: nowrap; width: 90px; }
.kv .v { padding: 1px 0; }
.sec { font-weight: bold; margin: 12px 0 4px; }
.grid th, .grid td { text-align: left; padding: 2px 10px 2px 0; font-size: 11px; }
.grid th { font-weight: bold; }
.grid.rt th, .grid.rt td { text-align: right; }
.faltas-irt { margin-bottom: 6px; }
.lines { margin-top: 8px; }
.lines th.l, .lines td { text-align: left; }
.lines th.r, .lines td.r { text-align: right; }
.lines thead th { border-bottom: 1px solid #111; padding: 5px 8px; font-weight: bold; }
.lines tbody td { padding: 4px 8px; }
.lines tbody tr.falta td { color: #666; font-style: italic; }
.lines tbody tr:first-child td { padding-top: 8px; }
.lines tfoot td { border-top: 1px solid #111; font-weight: bold; padding: 8px; }
.tot-l { text-align: right; }
.pay { margin-top: 30px; border-top: 1px solid #111; padding-top: 8px; }
.totpago-l { font-weight: bold; margin-right: 16px; }
.totpago-v { font-weight: bold; font-size: 14px; }
.foot { margin-top: 44px; font-style: italic; }
.foot .decl { margin-bottom: 30px; }
.foot .sig { border-top: 1px solid #666; width: 230px; }
